			case flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE:
				match, err = matchesBool(c, v)
			default:
				return resp, errors.ErrInvalid("unknown constraint type")
			}

			if err != nil {
				return resp, err
			}

