func TestBatchEvaluate(t *testing.T) {
	var (
		store = &storeMock{}
		s     = &Server{
			logger: logger,
			store:  store,
		}
	)

	store.On("GetFlag", mock.Anything, "foo").Return(enabledFlag, nil)

	store.On("GetEvaluationRules", mock.Anything, "foo").Return([]*storage.EvaluationRule{}, nil)

	resp, err := s.BatchEvaluate(context.TODO(), &flipt.BatchEvaluationRequest{
		RequestId: "12345",
		Requests: []*flipt.EvaluationRequest{
			{
				EntityId: "1",
				FlagKey:  "foo",
				Context: map[string]string{
					"bar": "boz",
				},
			},
		},
	})

	require.NoError(t, err)
	assert.Equal(t, "12345", resp.RequestId)
	assert.NotEmpty(t, resp.RequestDurationMillis)
	assert.NotNil(t, resp.Responses)
	assert.Equal(t, 1, len(resp.Responses))
	assert.False(t, resp.Responses[0].Match)
}

func TestBatchEvaluate_DisabledFlag(t *testing.T) {
	store := &storeMock{}
	s := &Server{logger: logger, store: store}
	store.On("GetFlag", mock.Anything, "foo").Return(enabledFlag, nil)
	store.On("GetFlag", mock.Anything, "disabled").Return(&flipt.Flag{Key: "disabled"}, nil)
	store.On("GetEvaluationRules", mock.Anything, "foo").Return([]*storage.EvaluationRule{}, nil)

	resp, err := s.BatchEvaluate(context.TODO(), &flipt.BatchEvaluationRequest{
		Requests: []*flipt.EvaluationRequest{
			{FlagKey: "foo", EntityId: "first"},
			{FlagKey: "disabled", EntityId: "second"},
			{FlagKey: "foo", EntityId: "third"},
		},
	})
	require.NoError(t, err)
	require.Len(t, resp.Responses, 3)
	for i, key := range []string{"foo", "disabled", "foo"} {
		entry := resp.Responses[i]
		assert.Equal(t, key, entry.FlagKey)
		assert.NotNil(t, entry.Timestamp)
		assert.Greater(t, entry.RequestDurationMillis, float64(0))
		assert.False(t, entry.Match)
		assert.Empty(t, entry.Value)
		assert.Empty(t, entry.SegmentKey)
	}
	assert.Equal(t, "second", resp.Responses[1].EntityId)
	assert.Equal(t, "third", resp.Responses[2].EntityId)
	assert.Greater(t, resp.RequestDurationMillis, float64(0))
	store.AssertExpectations(t)
}

